import{_ as d,C as e,o as c,c as h,j as r,a as t,G as s,a2 as n}from"./chunks/framework.BgSoyxN5.js";const k=JSON.parse('{"title":"Партнёрство TickerForge по здоровью портфеля | Диагностика портфеля и ко-брендинговые пилоты","description":"Партнёрское направление про диагностику портфеля: концентрация, отраслевая структура, денежная подушка и стресс-контекст для финансовых каналов, сообществ и консультантов.","frontmatter":{"title":"Партнёрство TickerForge по здоровью портфеля | Диагностика портфеля и ко-брендинговые пилоты","description":"Партнёрское направление про диагностику портфеля: концентрация, отраслевая структура, денежная подушка и стресс-контекст для финансовых каналов, сообществ и консультантов.","aside":false,"locale":"ru","alternateLocales":{"en":"/partners/portfolio-health","ru":"/ru/partners/portfolio-health"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/partners/portfolio-health.md","filePath":"ru/partners/portfolio-health.md","lastUpdated":1788362384000}'),_={name:"ru/partners/portfolio-health.md"},f={class:"partners-wide"};function u(m,a,v,g,T,P){const o=e("PartnerPageAnalytics"),i=e("PartnerCabinetCta"),p=e("PartnerReferralCta"),l=e("PartnerLeadForm");return c(),h("div",null,[a[0]||(a[0]=r("h1",{id:"партнерство-здоровье-портфеля",tabindex:"-1"},[t("Партнёрство: здоровье портфеля "),r("a",{class:"header-anchor",href:"#партнерство-здоровье-портфеля","aria-label":'Permalink to "Партнёрство: здоровье портфеля"'},"​")],-1)),a[1]||(a[1]=r("p",null,"Контент про диагностику портфеля для аудитории, у которой есть реальные портфели: концентрация, отраслевая структура, денежная подушка и стресс-контекст.",-1)),a[2]||(a[2]=r("p",null,[t("Это направление про портфели, а не про отдельные тикеры и не про рыночную программу. Исследования по компаниям — на странице "),r("a",{href:"/ru/partners/stock-analysis-and-ideas"},"Исследования в Telegram"),t(", рыночный и макро-контент — на странице "),r("a",{href:"/ru/partners/market-news"},"Рыночные новости"),t(".")],-1)),s(o,{offer:"portfolio_health",locale:"ru"}),a[3]||(a[3]=n('<div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="#partner-contact" data-partner-event="cta" data-partner-option="propose_pilot" data-analytics-placement="partner_hero">Обсудить портфельный пилот</a><a class="partners-button partners-button--secondary" href="#portfolio-formats" data-partner-event="cta" data-partner-option="see_formats" data-analytics-placement="partner_hero">Посмотреть форматы</a></div><p class="partners-locale-switch"><a href="/partners/portfolio-health" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><p class="partners-backlink">Это одно из трёх направлений партнёрства. <a href="/ru/partners">Все варианты партнёрства</a> · <a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a> · <a href="/ru/partners/market-news">Рыночные новости</a> · <a href="/ru/partners/requirements">Требования к партнёрам</a></p><p>TickerForge — образовательное ПО для поддержки решений. Это не инвестиционная рекомендация, не брокер и не управляющий: продукт не хранит активы и не совершает сделок.</p><h2 id="что-это-такое" tabindex="-1">Что это такое <a class="header-anchor" href="#что-это-такое" aria-label="Permalink to &quot;Что это такое&quot;">​</a></h2><p>У большинства аудиторий проблема не в одном тикере, а в портфеле: слишком много в одной бумаге, весь результат держится на одном секторе, нет денежной подушки и непонятно, что с этим сделает плохой квартал.</p><p>Это направление — про контент на такой основе: диагностика, которую читатель может прогнать по своим позициям, и обсуждение, которое после неё начинается в вашем канале.</p><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>Структура</span><strong>Из чего вообще состоит портфель?</strong><p>Концентрация, отраслевая структура, размеры позиций и денежная подушка в одном обзоре.</p></div><div class="partners-card"><span>Риск</span><strong>Что с ним сделает плохой сценарий?</strong><p>Стресс-тест: чувствительность к просадке и к росту на основе состава портфеля, кэша, экспозиции и бета-допущений.</p></div><div class="partners-card"><span>Продолжение</span><strong>Что изменилось с прошлого раза?</strong><p>Регулярный мониторинг превращает разовую проверку в постоянный разговор с аудиторией.</p></div></div><h2 id="portfolio-formats" tabindex="-1">Портфельные форматы <a class="header-anchor" href="#portfolio-formats" aria-label="Permalink to &quot;Портфельные форматы {#portfolio-formats}&quot;">​</a></h2><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Доступно для пилотов</span><strong>Диагностика портфеля</strong><p>Концентрация, отраслевая структура и денежная подушка — как пост или как повод для обсуждения в канале.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Проверка здоровья портфеля</strong><p>Проверка, которую аудитория делает сама по своим позициям через публичный сценарий импорта.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Стресс-тест портфеля</strong><p>Чувствительность к просадке и риск-контекст портфеля — как сценарий, а не как прогноз.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Отслеживание портфеля</strong><p>Регулярный мониторинг и алерты об изменениях, чтобы тема возвращалась в канал с новыми цифрами.</p></div></div></div><p><strong>Как это направление работает сейчас.</strong> Портфельные форматы обсуждаются под каждый пилот отдельно: в Partner Cabinet нет портфельного поста «в одно нажатие», потому что за таким постом должен стоять реальный портфель. На практике пилот использует публичный сценарий диагностики с вашими отслеживаемыми ссылками, а сам пост готовится совместно.</p>',11)),s(i,{locale:"ru"}),a[4]||(a[4]=n('<h2 id="как-проходит-портфельныи-пилот" tabindex="-1">Как проходит портфельный пилот <a class="header-anchor" href="#как-проходит-портфельныи-пилот" aria-label="Permalink to &quot;Как проходит портфельный пилот&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Назвать угол</strong><p>В форме ниже выберите направление «Здоровье портфеля» и форматы, которые зайдут вашей аудитории.</p></div><div><span>2</span><strong>Согласовать пилот</strong><p>Договариваемся, что показывает пост, в какой сценарий попадает аудитория и что именно измеряем.</p></div><div><span>3</span><strong>Опубликовать с отслеживаемыми ссылками</strong><p>Аудитория прогоняет диагностику сама, перейдя по вашей ссылке.</p></div><div><span>4</span><strong>Измерить и решить</strong><p>Клики, старты бота, импорты портфелей и реферальная привязка показывают, работает ли тема для канала.</p></div></div></div><h2 id="кому-подходит" tabindex="-1">Кому подходит <a class="header-anchor" href="#кому-подходит" aria-label="Permalink to &quot;Кому подходит&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>Авторам, у которых аудитория и так обсуждает свои портфели.</li><li>Консультантам и преподавателям, которые разбирают позиции с клиентами.</li><li>Сообществам, где регулярно спрашивают «а у меня не слишком большая концентрация?».</li><li>Каналам, которым нужна тема шире, чем разборы отдельных бумаг.</li></ul></div><p>Условия участия, обязательства по публикациям и правила доступа одинаковы для всех направлений и описаны на странице <a href="/ru/partners/requirements">требований к партнёрам</a>.</p>',5)),s(p,{eyebrow:"Реферальная программа",title:"Зарабатывайте на рекомендациях параллельно с пилотом",text:"Ambassador Program платит 20% от каждой платной подписки каждый месяц, пока приведённый пользователь остаётся активным. Это работает вместе с партнёрским пилотом: одна и та же аудитория может прийти по вашей отслеживаемой ссылке и оформить подписку по вашей реферальной.",note:"Страница программы пока доступна только на английском.",cta:"Посмотреть Ambassador Program"}),a[5]||(a[5]=n('<h2 id="чем-это-не-является" tabindex="-1">Чем это не является <a class="header-anchor" href="#чем-это-не-является" aria-label="Permalink to &quot;Чем это не является&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>Это партнёрское направление не включает:</p><ul><li>управление портфелем или ребалансировку за читателя</li><li>персональные инвестиционные рекомендации</li><li>брокерские услуги, хранение активов и исполнение сделок</li><li>прогнозы доходности и обещания результата</li></ul><p>Диагностика TickerForge описывает структуру и риск. Что с этим делать — решение самого читателя, при необходимости вместе с его консультантом.</p></div><h2 id="partner-contact" tabindex="-1">Обсудить портфельный пилот <a class="header-anchor" href="#partner-contact" aria-label="Permalink to &quot;Обсудить портфельный пилот {#partner-contact}&quot;">​</a></h2><p>Расскажите про аудиторию и про то, какую портфельную тему хотите запустить первой. Полезные детали: ссылка на канал или сообщество, размер аудитории, язык, как часто у вас заходит разговор про портфели и интересен ли ко-брендинг или white-label в будущем.</p>',4)),r("div",f,[s(l,{locale:"ru",source:"partners_portfolio_health","default-program":"PORTFOLIO_HEALTH"})]),a[6]||(a[6]=n('<h2 id="смотрите-также" tabindex="-1">Смотрите также <a class="header-anchor" href="#смотрите-также" aria-label="Permalink to &quot;Смотрите также&quot;">​</a></h2><ul><li><a href="/ru/partners">Все варианты партнёрства</a></li><li><a href="/ru/partners/cabinet">Как работает Partner Cabinet</a></li><li><a href="/ru/partners/requirements">Требования к партнёрам</a></li><li><a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a></li><li><a href="/ru/partners/market-news">Рыночные новости</a></li><li><a href="/import-portfolio">Проверка здоровья портфеля</a></li><li><a href="/ambassador">Реферальная программа Ambassador</a></li></ul>',2))])}const C=d(_,[["render",u]]);export{k as __pageData,C as default};
